code='''def transform(grid):
    """Project sparse markers between two offset parallel guide segments."""
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # The guide color is the non-background color forming the two long segments.
    candidates = [c for c,n in counts.items() if c != bg and n >= 8]
    best = None
    for color in candidates:
        for orient in ('v','h'):
            groups = {}
            if orient == 'v':
                for c in range(w):
                    rr=[r for r in range(h) if grid[r][c]==color]
                    if rr:
                        # Split into contiguous runs.
                        runs=[]; run=[rr[0]]
                        for r in rr[1:]:
                            if r==run[-1]+1: run.append(r)
                            else: runs.append(run); run=[r]
                        runs.append(run)
                        for run in runs:
                            if len(run)>=5: groups[(c,run[0],run[-1])]=len(run)
            else:
                for r in range(h):
                    cc=[c for c in range(w) if grid[r][c]==color]
                    if cc:
                        runs=[]; run=[cc[0]]
                        for c in cc[1:]:
                            if c==run[-1]+1: run.append(c)
                            else: runs.append(run); run=[c]
                        runs.append(run)
                        for run in runs:
                            if len(run)>=5: groups[(r,run[0],run[-1])]=len(run)
            segs=list(groups)
            for i,a in enumerate(segs):
                for b in segs[i+1:]:
                    if orient=='v':
                        if a[0]==b[0]: continue
                        score=min(abs(a[2]-a[1]),abs(b[2]-b[1]))
                    else:
                        if a[0]==b[0]: continue
                        score=min(abs(a[2]-a[1]),abs(b[2]-b[1]))
                    if best is None or score>best[0]: best=(score,color,orient,a,b)
    if best is None:
        return g
    _, frame, orient, a, b = best
    # Order guide segments along their long axis. Their offset maps marker
    # coordinates from one run to the other.
    if orient=='v':
        segs=sorted([a,b], key=lambda x:x[1])
        (c1,s1,e1),(c2,s2,e2)=segs
        markers=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg and grid[r][c]!=frame]
        # For each marker aligned with a rail's span, project to the other span.
        for r,c in markers:
            choices=[]
            if s1<=r<=e1: choices.append((0,c1,s1,e1))
            if s2<=r<=e2: choices.append((1,c2,s2,e2))
            if not choices: continue
            # choose the closest segment in the perpendicular direction
            side, rail, lo, hi=min(choices,key=lambda q:abs(c-q[1]))
            g[r][c]=4
            step=1 if rail>c else -1
            x=c+step
            while 0<=x<w and x!=rail:
                if grid[r][x] != frame: g[r][x]=next(v for v in counts if v not in (bg,frame))
                x+=step
            target = r + ((s2-s1) if side==0 else (s1-s2))
            if 0<=target<h:
                ink=next(v for v in counts if v not in (bg,frame))
                left,right=sorted((c1,c2))
                for x in range(left+1,right):
                    g[target][x]=ink
    else:
        segs=sorted([a,b], key=lambda x:x[1])
        (r1,s1,e1),(r2,s2,e2)=segs
        markers=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg and grid[r][c]!=frame]
        ink=next(v for v in counts if v not in (bg,frame))
        for r,c in markers:
            choices=[]
            if s1<=c<=e1: choices.append((0,r1,s1,e1))
            if s2<=c<=e2: choices.append((1,r2,s2,e2))
            if not choices: continue
            side,rail,lo,hi=min(choices,key=lambda q:abs(r-q[1]))
            g[r][c]=4
            step=1 if rail>r else -1
            x=r+step
            while 0<=x<h and x!=rail:
                if grid[x][c] != frame: g[x][c]=ink
                x+=step
            target=c+((s2-s1) if side==0 else (s1-s2))
            if 0<=target<w:
                top,bottom=sorted((r1,r2))
                for x in range(top+1,bottom): g[x][target]=ink
    return g
